151	    @Override
152	    @Transactional
153	    public void deleteOwner(Owner owner) throws DataAccessException {
154	        // Soft delete: retain the row and flag it deleted rather than removing it. Deleted owners
155	        // are then ignored by the create endpoint's duplicate and identity checks.
156	        owner.setDeleted(true);
