416	    /**
417	     * Computes an owner's deterministic household id: the first 12 upper-case hex characters of the
418	     * SHA-256 digest over the version-2 region code ({@link Owner#deriveIdentityRegion()}, which
419	     * mixes in the fixed {@code 'V2'} version tag), a {@code '|'} separator, the owner's normalized
420	     * last name, a {@code '|'} separator and its postcode
421	     * ({@code identityRegion + '|' + normalizedLastName + '|' + postcode}). Owners that share a last
422	     * name and postcode therefore map to the same household id automatically, without any explicit
423	     * linking. Returns {@code null} when the last name or postcode is absent or blank, since no
424	     * household can be formed without both.
425	     */
426	    @Override
427	    @Transactional(readOnly = true)
428	    public String computeHouseholdId(Owner owner) throws DataAccessException {
429	        if (owner == null) {
430	            return null;
431	        }
432	        String normalizedLastName = normalizeHouseholdField(owner.getLastName());
433	        String postcode = owner.getPostcode();
434	        if (normalizedLastName == null || normalizedLastName.isBlank()
435	            || postcode == null || postcode.isBlank()) {
436	            return null;
437	        }
438	        return HashUtils.sha256UpperHex(
439	            owner.deriveIdentityRegion() + "|" + normalizedLastName + "|" + postcode, 12);
440	    }
441	
442	    /**
443	     * Counts the owners that belong to the household identified by the given (deterministic)
444	     * household id, i.e. the number of owners currently sharing it. Used to size a household for
445	     * the membership-points calculation. Returns {@code 0} when the id is absent.
446	     */
447	    @Override
448	    @Transactional(readOnly = true)
449	    public int countOwnersByHouseholdId(String householdId) throws DataAccessException {
450	        if (householdId == null || householdId.isBlank()) {
451	            return 0;
452	        }
453	        return (int) ownerRepository.findAll().stream()
454	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
455	            .count();
456	    }
457	
458	    /**
459	     * Returns the existing, non-deleted owners that belong to the household identified by the given
460	     * (deterministic) household id, i.e. the current members of that household. Used to derive the
461	     * membership-level ceiling a new owner joining the household is subject to. Returns an empty
462	     * collection when the id is absent.
463	     */
464	    @Override
465	    @Transactional(readOnly = true)
466	    public Collection<Owner> findOwnersByHouseholdId(String householdId) throws DataAccessException {
467	        if (householdId == null || householdId.isBlank()) {
468	            return List.of();
469	        }
470	        return ownerRepository.findAll().stream()
471	            .filter(existing -> !existing.isDeleted())
472	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
473	            .toList();
474	    }
475	
476	    /**
477	     * Computes the membership-level ceiling for a new owner joining the household identified by the
478	     * given (deterministic) household id: one above the current maximum membershipLevel among the
479	     * existing (non-deleted) household members. The members' live household size is passed explicitly
480	     * to {@link Owner#membershipLevel(Integer)}, so no persistent state is mutated. Returns
481	     * {@code null} when the household has no existing member, so no cap applies to the new owner.
482	     */
483	    @Override
484	    @Transactional(readOnly = true)
485	    public Integer computeMembershipLevelCap(String householdId) throws DataAccessException {
486	        Collection<Owner> members = findOwnersByHouseholdId(householdId);
487	        if (members.isEmpty()) {
488	            return null;
489	        }
490	        int maxLevel = 0;
491	        for (Owner member : members) {
492	            int level = member.membershipLevel(members.size());
493	            if (level > maxLevel) {
494	                maxLevel = level;
495	            }
496	        }
497	        return maxLevel + 1;
498	    }
499	
500	    /**
501	     * Normalizes a household-identity field for comparison by trimming, collapsing internal
502	     * runs of whitespace to a single space and lower-casing, so values that differ only in
503	     * whitespace or letter case are treated as equal.
504	     */
505	    private static String normalizeHouseholdField(String value) {
506	        if (value == null) {
507	            return null;
508	        }
509	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
510	    }
