243	     * text is upper-cased and common street-type abbreviations are expanded (e.g.
244	     * {@code '  12  main  st '} becomes {@code '12 MAIN STREET'}). The required-field rule is
245	     * enforced separately; an address blank after normalization is rejected.
246	     */
247	    @Named("normalizeAddress")
248	    default String normalizeAddress(String address) {
249	        return AddressNormalizer.normalize(address);
250	    }
251	
