253	     * Normalizes a telephone number for persistence into canonical E.164 form (e.g.
254	     * {@code '0412 345 678'} becomes {@code '+61412345678'}). The formability rule is
255	     * enforced separately by {@code TelephoneValidation}.
256	     */
257	    @Named("normalizeTelephone")
258	    default String normalizeTelephone(String telephone) {
259	        return TelephoneNormalizer.toE164(telephone);
260	    }
261	
262	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
263	
264	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
265	
266	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
267	        OwnerPageDto ownerPageDto = new OwnerPageDto();
268	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
269	        ownerPageDto.setPage(ownerPage.getNumber());
270	        ownerPageDto.setSize(ownerPage.getSize());
271	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
272	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
273	        return ownerPageDto;
274	    }
275	}
